from datetime import datetime, timezone
from typing import Any, Iterable

from composio import Composio

USER_ID = "zealt-user01"
REPORT_PATH = "/home/user/morning_sweep.txt"
EXPECTED_ACCOUNT_IDS = ["work-github", "personal-github"]
TOOL_SLUG = "GITHUB_LIST_ISSUES_ASSIGNED_TO_THE_AUTHENTICATED_USER"


def _normalize_accounts(items: Iterable[Any]) -> list[dict[str, Any]]:
    normalized = []
    for item in items:
        normalized.append(
            {
                "id": getattr(item, "id", None),
                "alias": getattr(item, "alias", None),
                "toolkit": getattr(item, "toolkit", None),
                "status": getattr(item, "status", None),
            }
        )
    return normalized


def _select_accounts(connected: list[dict[str, Any]]) -> list[dict[str, Any]]:
    by_id = {item["id"]: item for item in connected if item.get("id")}
    by_alias = {item["alias"]: item for item in connected if item.get("alias")}
    remaining = [item for item in connected if item.get("id") not in by_id]

    selected = []
    for expected_id in EXPECTED_ACCOUNT_IDS:
        if expected_id in by_id:
            selected.append({**by_id[expected_id], "label": expected_id})
            continue
        if expected_id in by_alias:
            selected.append({**by_alias[expected_id], "label": expected_id})
            continue
        if remaining:
            fallback = remaining.pop(0)
            selected.append({**fallback, "label": f"{expected_id} (fallback)"})
            continue
        selected.append({"id": expected_id, "label": expected_id, "missing": True})

    return selected


def _extract_issues(payload: Any) -> list[dict[str, Any]]:
    if payload is None:
        return []
    if isinstance(payload, dict) and "data" in payload:
        payload = payload.get("data")
    if isinstance(payload, dict) and "items" in payload:
        payload = payload.get("items")
    if isinstance(payload, list):
        return [issue for issue in payload if isinstance(issue, dict)]
    return []


def _render_issue(issue: dict[str, Any]) -> str:
    title = issue.get("title") or "(no title)"
    number = issue.get("number")
    html_url = issue.get("html_url") or issue.get("url") or ""
    repository = issue.get("repository") or {}
    repo_name = repository.get("full_name") or issue.get("repository_url") or ""
    state = issue.get("state") or "unknown"
    updated_at = issue.get("updated_at") or ""

    details = f"- {title}"
    if number is not None:
        details += f" (#{number})"
    if repo_name:
        details += f" | repo: {repo_name}"
    if state:
        details += f" | state: {state}"
    if updated_at:
        details += f" | updated: {updated_at}"
    if html_url:
        details += f" | {html_url}"
    return details


def run() -> str:
    composio = Composio()

    connected_response = composio.client.connected_accounts.list(
        user_ids=[USER_ID],
        toolkit_slugs=["github"],
    )
    connected_accounts = _normalize_accounts(connected_response.items)
    selected_accounts = _select_accounts(connected_accounts)

    session = composio.client.tool_router.session.create(
        user_id=USER_ID,
        multi_account={"enable": True, "require_explicit_selection": True},
        toolkits={"enable": ["github"]},
    )
    session_id = session.id

    lines = []
    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%SZ")
    lines.append(f"Morning Sweep Report ({timestamp})")

